// Package indexroom implements chain ingestion with optional block
// timestamps, reorg handling, consistent paginated transaction queries, and
// time-bucketed transaction statistics over the main chain.
package indexroom

import (
	"fmt"
	"sync"
	"unicode/utf8"
)

// Block is one ingested block with its transactions.
//
// Time is the optional block timestamp as non-negative Unix seconds. A nil
// pointer means the block carries no timestamp and is distinct from a
// timestamp of zero. Append and Reorg reject negative values; stored blocks
// keep their own copy, so mutating the pointer or its target after a call
// never affects the index. Block timestamps need not be monotonic: equal
// values and values that decrease with height are both accepted.
type Block struct {
	Height int64
	// Hash, Parent, and every Txs identifier must be valid UTF-8; Append and
	// Reorg reject a block carrying invalid bytes rather than letting a
	// snapshot export silently rewrite them to U+FFFD. Txs keeps empty and
	// duplicated identifiers, order, case, and surrounding whitespace
	// exactly as given.
	Hash   string
	Parent string
	Txs    []string
	Time   *int64
}

// Index is the durable chain view.
//
// Append, Reorg, QueryTxs, QueryTimeStats, Export, and Restore are safe for
// concurrent use; the exported fields are meant for read-only inspection
// after all calls have finished.
type Index struct {
	Blocks map[int64]Block
	ByHash map[string]int64
	Tip    int64

	mu  sync.Mutex
	key [32]byte
}

// New returns an empty index.
func New() *Index {
	return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}, key: newKey()}
}

// reorgAppliedHookLocked is a test-only rendezvous invoked from Reorg once
// the alternate branch has fully replaced the old tip range, while index.mu
// is still held and before the call returns. It is nil in production; reorg
// regression tests park a successful reorg here with the new chain already in
// effect, so a QueryTimeStats issued at that instant is forced to wait and,
// once it runs, must observe the complete new chain.
var reorgAppliedHookLocked func(newTip int64)

// Append accepts a block only when it extends the current tip, keeping the
// chain linear. Re-submitting a block identical to one already on the main
// chain is a successful no-op. A block whose hash, parent, or any transaction
// identifier carries invalid UTF-8 is rejected with an error naming the
// height and field (and the zero-based tx position); a rejected append leaves
// the index untouched.
func (index *Index) Append(block Block) error {
	index.mu.Lock()
	defer index.mu.Unlock()
	return index.appendLocked(block)
}

func (index *Index) appendLocked(block Block) error {
	if err := validateBlockEncoding(block); err != nil {
		return err
	}
	if block.Hash == "" {
		return errInvalid("block needs a hash")
	}
	if block.Time != nil && *block.Time < 0 {
		return errInvalid("block time must not be negative")
	}
	if index.Tip == 0 {
		// Empty index: only the first block at height 1 is accepted; its
		// parent becomes the chain start identifier and need not be indexed.
		if block.Height != 1 {
			return errInvalid("first block must be at height 1")
		}
		index.storeLocked(block)
		return nil
	}
	if old, exists := index.Blocks[block.Height]; exists {
		if sameBlock(old, block) {
			return nil
		}
		return errInvalid("height already indexed with different content")
	}
	if block.Height != index.Tip+1 {
		return errInvalid("block height must extend the current tip")
	}
	if block.Parent != index.Blocks[index.Tip].Hash {
		return errInvalid("parent does not match the current tip")
	}
	if _, exists := index.ByHash[block.Hash]; exists {
		return errInvalid("hash already indexed at another height")
	}
	index.storeLocked(block)
	return nil
}

// Reorg replaces the tip range with an alternate branch and reports the
// dropped old heights in ascending order. The branch is validated in full
// before anything is applied — including UTF-8 validity of every block's
// hash, parent, and transaction identifiers, even in the last block — so a
// rejected reorg leaves the index exactly as it was and reports no dropped
// heights. Heights whose old block is identical to the new one are not
// reported; re-submitting the branch already in effect returns an empty list.
func (index *Index) Reorg(blocks []Block) ([]int64, error) {
	index.mu.Lock()
	defer index.mu.Unlock()

	if len(blocks) == 0 {
		return nil, errInvalid("empty branch")
	}
	// Every identifier must be valid UTF-8 before any lookup or mutation.
	// The first block's parent need not be indexed, but it still has to be
	// encodable, and an error in the last block must reject the whole branch.
	for _, block := range blocks {
		if err := validateBlockEncoding(block); err != nil {
			return nil, err
		}
	}
	ancestor, ok := index.ByHash[blocks[0].Parent]
	if !ok {
		return nil, errInvalid("branch parent is unknown")
	}
	if blocks[0].Height != ancestor+1 {
		return nil, errInvalid("branch must start at the ancestor height plus one")
	}
	seen := make(map[string]bool, len(blocks))
	for i, block := range blocks {
		if block.Hash == "" {
			return nil, errInvalid("block needs a hash")
		}
		if block.Time != nil && *block.Time < 0 {
			return nil, errInvalid("block time must not be negative")
		}
		if seen[block.Hash] {
			return nil, errInvalid("duplicate hash inside branch")
		}
		seen[block.Hash] = true
		if height, exists := index.ByHash[block.Hash]; exists && height <= ancestor {
			return nil, errInvalid("hash conflicts with a retained block")
		}
		if i > 0 {
			prev := blocks[i-1]
			if block.Height != prev.Height+1 {
				return nil, errInvalid("branch heights must be consecutive")
			}
			if block.Parent != prev.Hash {
				return nil, errInvalid("branch parent does not match the previous block")
			}
		}
	}

	// Everything validated; compute the dropped heights before mutating.
	newTip := blocks[len(blocks)-1].Height
	dropped := []int64{}
	for height := ancestor + 1; height <= index.Tip; height++ {
		if height > newTip {
			dropped = append(dropped, height)
			continue
		}
		if !sameBlock(index.Blocks[height], blocks[height-blocks[0].Height]) {
			dropped = append(dropped, height)
		}
	}
	for height := ancestor + 1; height <= index.Tip; height++ {
		delete(index.ByHash, index.Blocks[height].Hash)
		delete(index.Blocks, height)
	}
	index.Tip = ancestor
	for _, block := range blocks {
		index.storeLocked(block)
	}
	if reorgAppliedHookLocked != nil {
		reorgAppliedHookLocked(index.Tip)
	}
	return dropped, nil
}

// storeLocked records a validated block, copying its transactions and
// timestamp so later caller-side mutation cannot alter the stored block.
func (index *Index) storeLocked(block Block) {
	if block.Txs != nil {
		txs := make([]string, len(block.Txs))
		copy(txs, block.Txs)
		block.Txs = txs
	}
	if block.Time != nil {
		t := *block.Time
		block.Time = &t
	}
	index.Blocks[block.Height] = block
	index.ByHash[block.Hash] = block.Height
	index.Tip = block.Height
}

// validateBlockEncoding rejects a block whose hash, parent, or any
// transaction identifier contains invalid UTF-8 bytes. JSON snapshots can
// only carry valid UTF-8 — the encoder would silently rewrite bad bytes to
// U+FFFD, merging distinct identifiers after a restore — so such a block can
// never enter the index. The error names the block height and the field; a
// bad transaction identifier also names its zero-based position. A genuine
// U+FFFD is valid UTF-8 and is never rejected by this check.
func validateBlockEncoding(block Block) error {
	if !utf8.ValidString(block.Hash) {
		return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "hash"))
	}
	if !utf8.ValidString(block.Parent) {
		return errInvalid(fmt.Sprintf("block at height %d: field %q contains invalid UTF-8 bytes", block.Height, "parent"))
	}
	for position, tx := range block.Txs {
		if !utf8.ValidString(tx) {
			return errInvalid(fmt.Sprintf("block at height %d: field %q element %d contains invalid UTF-8 bytes", block.Height, "txs", position))
		}
	}
	return nil
}

// sameBlock reports whether two blocks are identical: same height, hash,
// parent, transactions in order, and timestamp presence and value. An empty
// tx list equals a missing one, but a missing timestamp never equals zero.
func sameBlock(a, b Block) bool {
	if a.Height != b.Height || a.Hash != b.Hash || a.Parent != b.Parent {
		return false
	}
	if len(a.Txs) != len(b.Txs) {
		return false
	}
	for i := range a.Txs {
		if a.Txs[i] != b.Txs[i] {
			return false
		}
	}
	if (a.Time == nil) != (b.Time == nil) {
		return false
	}
	return a.Time == nil || *a.Time == *b.Time
}

type errInvalid string

func (e errInvalid) Error() string { return string(e) }

package indexroom

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"slices"
	"strconv"
	"unicode/utf8"
)

// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
// truncated JSON, trailing data after the object, an unknown version,
// missing, mistyped, unknown, or duplicated fields, a null where version,
// tip, height, hash, parent, or a transaction identifier is required,
// heights that do not ascend consecutively from 1, an empty or duplicated
// hash, a broken parent link, a version-2 timestamp that is missing or
// neither null nor a non-negative integer, a hash, parent, or transaction
// identifier whose JSON string carries invalid UTF-8 bytes or unpaired or
// misordered Unicode surrogate escapes, or a tip that disagrees with the
// block list. A rejected restore never changes the index.
var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")

const (
	// snapshotVersion1 is the timestamp-less layout. It stays readable
	// indefinitely; its blocks restore with missing timestamps.
	snapshotVersion1 = 1
	// snapshotVersion2 adds a required timestamp field to every block:
	// either a non-negative Unix-seconds integer or null for missing time.
	snapshotVersion2 = 2
)

// snapshotDoc is the wire form of an exported main chain. Both layout
// versions share one shape: Version selects whether every block carries its
// Timestamp field.
type snapshotDoc struct {
	Version int64           `json:"version"`
	Tip     int64           `json:"tip"`
	Blocks  []snapshotBlock `json:"blocks"`
}

// snapshotBlock is the wire form of one block, shared by both versions.
// Height, hash, parent, and the transaction list follow the same rules in
// either layout. The timestamp is version 2 only and carried as a raw
// literal: nil is omitted altogether (version 1), "null" marks a missing
// time, and integer bytes render the Unix-seconds value (version 2). It
// stays the final field in every layout.
type snapshotBlock struct {
	Height    int64           `json:"height"`
	Hash      string          `json:"hash"`
	Parent    string          `json:"parent"`
	Txs       []string        `json:"txs"`
	Timestamp json.RawMessage `json:"timestamp,omitempty"`
}

// Export writes the current main chain to w as a JSON snapshot: a single
// object with version, tip, and the blocks ordered by ascending height, each
// carrying its transactions in order. The same main chain always produces
// the same bytes, regardless of the reorg, restore, or query history that
// led to it. Only blocks in effect at export time appear; nothing the index
// once held and later dropped is included.
//
// A chain whose blocks all lack timestamps keeps the original version-1
// layout, byte for byte. As soon as any block carries a timestamp the
// document is version 2 and every block includes a timestamp field: a
// non-negative integer or null for a missing timestamp.
//
// Export observes one complete chain state and never modifies the index.
// The chain is copied under the lock and serialized afterwards, so queries
// and appends proceed while the stream is still being written. A write
// failure is reported and leaves the index untouched.
func (index *Index) Export(w io.Writer) error {
	doc := index.snapshotChain()
	raw, err := json.Marshal(doc)
	if err != nil {
		panic(err) // snapshot docs only contain marshalable fields
	}
	n, err := w.Write(raw)
	if err != nil {
		return fmt.Errorf("indexroom: export snapshot: %w", err)
	}
	if n != len(raw) {
		return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
	}
	return nil
}

// snapshotChain copies the current main chain into the export wire
// form: blocks by ascending height, each with its transactions copied in
// original order. This is the single place that turns stored blocks into the
// shared document fields, so both layout versions keep identical rules for
// height, hash, parent, and the transaction list; the only version-dependent
// field is the timestamp literal.
//
// The version is selected from the same chain copy. Any block carrying a
// timestamp — even a zero — makes the document version 2, after which every
// block gets a timestamp field, null where its time is missing; a chain
// whose blocks all lack times stays version 1 with no timestamp field.
func (index *Index) snapshotChain() snapshotDoc {
	index.mu.Lock()
	defer index.mu.Unlock()
	version := int64(snapshotVersion1)
	for height := int64(1); height <= index.Tip; height++ {
		if index.Blocks[height].Time != nil {
			version = snapshotVersion2
			break
		}
	}
	doc := snapshotDoc{
		Version: version,
		Tip:     index.Tip,
		Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
	}
	for height := int64(1); height <= index.Tip; height++ {
		block := index.Blocks[height]
		txs := make([]string, len(block.Txs))
		copy(txs, block.Txs)
		entry := snapshotBlock{
			Height: block.Height,
			Hash:   block.Hash,
			Parent: block.Parent,
			Txs:    txs,
		}
		if version == snapshotVersion2 {
			entry.Timestamp = snapshotTimestampLiteral(block.Time)
		}
		doc.Blocks = append(doc.Blocks, entry)
	}
	return doc
}

// snapshotMissingTimestamp is the raw JSON literal written for a block whose
// time is missing in a version-2 document.
var snapshotMissingTimestamp = json.RawMessage("null")

// snapshotTimestampLiteral renders a stored block time as its version-2
// timestamp literal: null for a missing time, otherwise its non-negative
// Unix-seconds value as a bare integer. Stored times are guaranteed
// non-negative by Append, Reorg, and Restore validation.
func snapshotTimestampLiteral(time *int64) json.RawMessage {
	if time == nil {
		return snapshotMissingTimestamp
	}
	return json.RawMessage(strconv.AppendInt(nil, *time, 10))
}

// restoreAppliedHookLocked is a test-only rendezvous invoked from Restore
// once the snapshot chain has fully replaced the old main chain, while
// index.mu is still held and before the call returns. It is nil in
// production; restore regression tests park a successful restore here with
// the new chain already in effect, so a QueryTimeStats issued at that
// instant is forced to wait and, once it runs, must observe the complete
// new chain.
var restoreAppliedHookLocked func(newTip int64)

// Restore replaces the whole main chain with the snapshot read from r. The
// input must be exactly one snapshot object, optionally followed by
// whitespace; every block is validated — including heights ascending from 1,
// non-empty unique hashes, and parent linkage — before anything is applied.
// The first block's parent is exempt from linkage: it names the chain start
// and need not be indexed.
//
// The replacement takes effect as one complete operation: on success the
// index holds exactly the snapshot chain with no leftover heights or hashes,
// and on any failure — a read error or an invalid block discovered at the
// very end — the current chain and every previously issued cursor remain as
// they were. The stream is consumed and validated before the lock is taken,
// so the index stays queryable and appendable while the restore is reading.
//
// After a successful restore, cursors issued earlier by this same index keep
// working wherever the pinned range still matches and the tip still covers
// it; otherwise continuations fail with ErrQueryChanged as usual.
func (index *Index) Restore(r io.Reader) error {
	tip, blocks, err := parseSnapshot(r)
	if err != nil {
		return err
	}
	stored := make(map[int64]Block, len(blocks))
	byHash := make(map[string]int64, len(blocks))
	for _, block := range blocks {
		stored[block.Height] = block
		byHash[block.Hash] = block.Height
	}
	index.mu.Lock()
	index.Blocks = stored
	index.ByHash = byHash
	index.Tip = tip
	if restoreAppliedHookLocked != nil {
		restoreAppliedHookLocked(tip)
	}
	index.mu.Unlock()
	return nil
}

// snapshotReader mediates between the snapshot's io.Reader and the JSON
// decoder so a fault the reader reports mid-document cannot be mistaken for a
// truncated document.
//
// json.Decoder turns a clean io.EOF after a partial JSON value into
// io.ErrUnexpectedEOF, and its token/peek path also drops any error that
// arrives together with the final bytes of a chunk. Either behavior makes a
// reader-reported io.ErrUnexpectedEOF — bare or wrapped — indistinguishable
// from an honestly truncated stream, and can hide the fault altogether.
//
// snapshotReader therefore observes every underlying read: only the bare
// io.EOF sentinel — the exact value, not anything that merely errors.Is-
// matches it — passes through as the normal end of input. A wrapped io.EOF,
// or a combined error such as errors.Join(io.EOF, fault), is a read failure
// like any other error: it is remembered in fault and, when it arrived
// together with bytes, withheld until the following read. The decoder
// consumes the delivered bytes first and then receives the fault as a
// separate error-only read, where it cannot be swallowed. The fault is
// sticky afterwards, so a reader that oddly resumes after failing can never
// let the snapshot be applied once a failure has been reported, and a later
// clean io.EOF cannot erase a fault already received.
type snapshotReader struct {
	r       io.Reader
	fault   error // first error other than the bare io.EOF reported by r, if any
	pending bool  // fault is due on the next read
}

func (s *snapshotReader) Read(p []byte) (int, error) {
	if s.pending {
		s.pending = false
		return 0, s.fault
	}
	if s.fault != nil {
		return 0, s.fault
	}
	n, err := s.r.Read(p)
	// Identity comparison on purpose: the JSON decoder treats only the bare
	// io.EOF as the normal end of input the same way. A wrapped io.EOF, or a
	// combined error carrying io.EOF alongside a storage fault, must reach
	// the fault path instead of passing for a clean end.
	if err == nil || err == io.EOF {
		return n, err
	}
	if s.fault == nil {
		s.fault = err
	}
	if n > 0 {
		s.pending = true
		return n, nil
	}
	return 0, err
}

// parseSnapshot reads and fully validates one snapshot document. It returns
// the tip height and the validated blocks in ascending height order.
func parseSnapshot(r io.Reader) (int64, []Block, error) {
	// A fault the underlying reader reports mid-document — including one
	// delivered together with usable bytes — is observed via snapshotReader
	// rather than inferred from the JSON decoder, which would conflate it with
	// a clean io.EOF on truncated input.
	reader := &snapshotReader{r: r}
	dec := json.NewDecoder(reader)
	// classify maps a decoder failure onto the snapshot error model, but a
	// fault observed on the underlying reader always wins: the decoder turns a
	// clean io.EOF after truncated input into io.ErrUnexpectedEOF, so the
	// presence of a real reader fault is the only reliable way to tell a read
	// failure from an honestly truncated document. Field context carried by
	// err (for example which field was being read) is preserved, and the
	// recorded fault stays in the chain even when the decoder reports a
	// separate content error from bytes already buffered.
	classify := func(err error) error {
		if reader.fault == nil {
			return classifySnapshotErr(err)
		}
		if !errors.Is(err, reader.fault) {
			err = fmt.Errorf("%w: %v", reader.fault, err)
		}
		return fmt.Errorf("indexroom: read snapshot: %w", err)
	}
	// reject reports a content error found in bytes already decoded, unless
	// the underlying reader has already reported a fault: a stream that
	// failed cannot be known to be complete, so the read failure takes
	// precedence over any content error the same batch of bytes exposed —
	// even over a complete, otherwise valid snapshot. Only a fault already
	// observed wins; content errors found before the reader has failed are
	// reported as-is, without reading ahead to look for one.
	reject := func(err error) error {
		if reader.fault != nil {
			return fmt.Errorf("indexroom: read snapshot: %w", reader.fault)
		}
		return err
	}
	// Top-level fields are captured raw so blocks can be parsed with the
	// strict schema matching the declared version, whatever the field order,
	// and so null can be told apart from a zero value.
	fields, err := readSnapshotObject(dec, snapshotDocSpec, classify, reject, "version", "tip", "blocks")
	if err != nil {
		return 0, nil, err
	}
	// Only whitespace may follow the snapshot object. A reader fault that
	// arrived together with the document's final bytes is held back by
	// snapshotReader and surfaces here, ahead of any content validation below:
	// once the stream failed, the document cannot be known to be complete, so
	// the read failure takes precedence even when the buffered bytes already
	// contain trailing data or a complete object.
	if reader.fault != nil {
		return 0, nil, fmt.Errorf("indexroom: read snapshot: %w", reader.fault)
	}
	if _, err := dec.Token(); err != io.EOF {
		if err == nil {
			// The read that fetched the trailing bytes may itself have
			// reported a fault; that failure still outranks the extra data.
			return 0, nil, reject(invalidSnapshot("trailing data after the snapshot object"))
		}
		return 0, nil, classify(err)
	}

	if err := requireSnapshotFields(snapshotDocSpec, fields, "version", "tip", "blocks"); err != nil {
		return 0, nil, err
	}
	version, err := snapshotInt64(fields["version"], "version")
	if err != nil {
		return 0, nil, err
	}
	tip, err := snapshotInt64(fields["tip"], "tip")
	if err != nil {
		return 0, nil, err
	}
	if version != snapshotVersion1 && version != snapshotVersion2 {
		return 0, nil, invalidSnapshot("unsupported version %d", version)
	}

	blockDec := json.NewDecoder(bytes.NewReader(fields["blocks"]))
	blocks, err := parseSnapshotBlocks(blockDec, version)
	if err != nil {
		return 0, nil, err
	}
	if _, err := blockDec.Token(); err != io.EOF {
		if err == nil {
			return 0, nil, invalidSnapshot("trailing data after the blocks array")
		}
		return 0, nil, classifySnapshotErr(err)
	}

	lastHeight := int64(0)
	if len(blocks) > 0 {
		lastHeight = blocks[len(blocks)-1].Height
	}
	if tip != lastHeight {
		return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
	}
	return tip, blocks, nil
}

// parseSnapshotBlocks reads the blocks array value, validating heights,
// hashes, parent links, and (for version 2) timestamps as it goes.
func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, classifySnapshotErr(err)
	}
	if delim, ok := tok.(json.Delim); !ok || delim != '[' {
		return nil, invalidSnapshot("field %q must be an array", "blocks")
	}
	blocks := []Block{}
	seenHash := map[string]bool{}
	for dec.More() {
		var block Block
		if version == snapshotVersion2 {
			block, err = parseSnapshotBlockV2(dec)
		} else {
			block, err = parseSnapshotBlock(dec)
		}
		if err != nil {
			return nil, err
		}
		want := int64(len(blocks) + 1)
		if block.Height != want {
			return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
		}
		if block.Hash == "" {
			return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
		}
		if seenHash[block.Hash] {
			return nil, invalidSnapshot("duplicate hash %q", block.Hash)
		}
		seenHash[block.Hash] = true
		// The first block's parent names the chain start and is exempt from
		// linkage; every later block must point at its predecessor.
		if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
			return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
		}
		blocks = append(blocks, block)
	}
	if _, err := dec.Token(); err != nil { // closing ']'
		return nil, classifySnapshotErr(err)
	}
	return blocks, nil
}

// parseSnapshotBlock reads one version-1 block object, requiring exactly the
// fields height, hash, parent, and txs.
func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
	var block Block
	fields, err := readSnapshotObject(dec, snapshotBlockSpec, classifySnapshotErr, snapshotContentErr, "height", "hash", "parent", "txs")
	if err != nil {
		return block, err
	}
	return finishSnapshotBlock(fields)
}

// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
// the fields height, hash, parent, txs, and timestamp. Timestamp must be
// null or a non-negative integer; the block returns a nil time for null.
func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
	var block Block
	fields, err := readSnapshotObject(dec, snapshotBlockSpec, classifySnapshotErr, snapshotContentErr, "height", "hash", "parent", "txs", "timestamp")
	if err != nil {
		return block, err
	}
	if err := requireSnapshotFields(snapshotBlockSpec, fields, "timestamp"); err != nil {
		return block, err
	}
	block, err = finishSnapshotBlock(fields)
	if err != nil {
		return block, err
	}
	t, err := parseSnapshotTimestamp(fields["timestamp"])
	if err != nil {
		return Block{}, err
	}
	block.Time = t
	return block, nil
}

// snapshotObjectSpec describes one object level of the snapshot document:
// which error reasons it reports when the value is not an object or a field
// is repeated, unrecognized, or required but absent. The two levels share
// the reading and validation rules through readSnapshotObject and
// requireSnapshotFields; the spec keeps each level's own wording so an error
// still says whether the top-level object or a block is at fault.
type snapshotObjectSpec struct {
	shape     string // reason when the value is not a JSON object
	duplicate string // reason format naming a repeated field
	unknown   string // reason format naming an unrecognized field
	missing   string // reason format naming a required field that never appeared
}

var (
	// snapshotDocSpec is the top-level snapshot object.
	snapshotDocSpec = snapshotObjectSpec{
		shape:     "snapshot must be a single JSON object",
		duplicate: "duplicate field %q",
		unknown:   "unknown field %q",
		missing:   "missing field %q",
	}
	// snapshotBlockSpec is one block object inside the blocks array.
	snapshotBlockSpec = snapshotObjectSpec{
		shape:     "block must be a JSON object",
		duplicate: "duplicate block field %q",
		unknown:   "unknown block field %q",
		missing:   "block is missing field %q",
	}
)

// readSnapshotObject reads one JSON object and captures each known field's
// raw value, applying the rules both object levels share: the value must be
// an object, every key is matched by its decoded name (so a Unicode-escaped
// spelling of a field still counts as that field), a repeated or unknown
// field is rejected, and each known field's raw bytes are kept for later
// decoding. Fields are decoded only after the whole object is read, so a
// null can be rejected per field and a value error can be reported whatever
// order the fields arrive in.
//
// classify maps a decoder failure onto the snapshot error model for the
// level's input source, and reject reports a content error found in bytes
// already decoded; the top level passes its reader-fault-aware closures,
// while a level decoded from already-buffered bytes passes
// classifySnapshotErr and snapshotContentErr.
func readSnapshotObject(dec *json.Decoder, spec snapshotObjectSpec, classify, reject func(error) error, known ...string) (map[string]json.RawMessage, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, classify(err)
	}
	if delim, ok := tok.(json.Delim); !ok || delim != '{' {
		return nil, reject(invalidSnapshot("%s", spec.shape))
	}
	fields := map[string]json.RawMessage{}
	for dec.More() {
		key, err := snapshotKey(dec)
		if err != nil {
			return nil, classify(err)
		}
		if _, dup := fields[key]; dup {
			return nil, reject(invalidSnapshot(spec.duplicate, key))
		}
		if !slices.Contains(known, key) {
			return nil, reject(invalidSnapshot(spec.unknown, key))
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return nil, classify(fmt.Errorf("field %q: %w", key, err))
		}
		fields[key] = raw
	}
	if _, err := dec.Token(); err != nil { // closing '}'
		return nil, classify(err)
	}
	return fields, nil
}

// requireSnapshotFields verifies that every required field appeared in the
// object, reporting the first absent one with the level's own wording.
func requireSnapshotFields(spec snapshotObjectSpec, fields map[string]json.RawMessage, required ...string) error {
	for _, field := range required {
		if _, ok := fields[field]; !ok {
			return invalidSnapshot(spec.missing, field)
		}
	}
	return nil
}

// snapshotContentErr reports a content error as-is. It is the reject
// function for object levels decoded from already-buffered bytes, where no
// underlying read failure can outrank a content error.
func snapshotContentErr(err error) error { return err }

// finishSnapshotBlock decodes the shared block fields from their raw values,
// requiring height, hash, parent, and txs and rejecting null for each.
func finishSnapshotBlock(fields map[string]json.RawMessage) (Block, error) {
	var block Block
	if err := requireSnapshotFields(snapshotBlockSpec, fields, "height", "hash", "parent", "txs"); err != nil {
		return block, err
	}
	var err error
	if block.Height, err = snapshotInt64(fields["height"], "height"); err != nil {
		return block, err
	}
	if block.Hash, err = snapshotString(fields["hash"], "hash", block.Height); err != nil {
		return block, err
	}
	if block.Parent, err = snapshotString(fields["parent"], "parent", block.Height); err != nil {
		return block, err
	}
	txs, err := parseSnapshotTxs(json.NewDecoder(bytes.NewReader(fields["txs"])), block.Height)
	if err != nil {
		return block, err
	}
	block.Txs = txs
	return block, nil
}

// snapshotInt64 decodes one required integer field, rejecting null rather
// than letting it pass as zero.
func snapshotInt64(raw json.RawMessage, field string) (int64, error) {
	if isSnapshotNull(raw) {
		return 0, invalidSnapshot("field %q must not be null", field)
	}
	var v int64
	if err := json.Unmarshal(raw, &v); err != nil {
		return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
	}
	return v, nil
}

// snapshotString decodes one required string field, rejecting null rather
// than letting it pass as the empty string. The raw literal is also checked
// for invalid UTF-8 bytes and unpaired or misordered \uXXXX surrogate
// escapes, which the decoder would otherwise silently rewrite to U+FFFD;
// height identifies the block the field belongs to in the error.
func snapshotString(raw json.RawMessage, field string, height int64) (string, error) {
	if isSnapshotNull(raw) {
		return "", invalidSnapshot("field %q must not be null", field)
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
	}
	if !validSnapshotString(raw) {
		return "", invalidSnapshot("block at height %d: field %q has invalid UTF-8 or unpaired surrogate escapes", height, field)
	}
	return s, nil
}

// isSnapshotNull reports whether a raw field value is the JSON null literal.
func isSnapshotNull(raw json.RawMessage) bool {
	return string(raw) == "null"
}

// validSnapshotString reports whether raw is a JSON string literal whose
// content is valid UTF-8 and whose \uXXXX escapes contain no unpaired or
// misordered surrogates. The JSON decoder accepts both defects silently,
// rewriting the bad parts to U+FFFD, which could merge distinct identifiers;
// the raw bytes are checked here before the decoded value is trusted. A
// genuine U+FFFD — written literally or as a \ufffd escape — is valid
// UTF-8 and passes.
func validSnapshotString(raw json.RawMessage) bool {
	if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
		return false
	}
	body := raw[1 : len(raw)-1]
	for i := 0; i < len(body); {
		b := body[i]
		switch {
		case b == '\\':
			if i+1 >= len(body) {
				return false
			}
			if body[i+1] != 'u' {
				i += 2 // \", \\, \/, \b, \f, \n, \r, \t
				continue
			}
			code, ok := snapshotHex4(body, i+2)
			if !ok {
				return false
			}
			i += 6
			switch {
			case code >= 0xD800 && code <= 0xDBFF:
				// A high surrogate is only valid as the first half of a
				// pair; the low half must follow immediately as an escape.
				if i+6 > len(body) || body[i] != '\\' || body[i+1] != 'u' {
					return false
				}
				low, ok := snapshotHex4(body, i+2)
				if !ok || low < 0xDC00 || low > 0xDFFF {
					return false
				}
				i += 6
			case code >= 0xDC00 && code <= 0xDFFF:
				return false // a low surrogate cannot appear on its own
			}
		case b < utf8.RuneSelf:
			i++
		default:
			// DecodeRune returns RuneError with size 1 for invalid
			// encoding; a genuine U+FFFD decodes with size 3.
			r, size := utf8.DecodeRune(body[i:])
			if r == utf8.RuneError && size <= 1 {
				return false
			}
			i += size
		}
	}
	return true
}

// snapshotHex4 reads four hexadecimal digits starting at b[i].
func snapshotHex4(b []byte, i int) (rune, bool) {
	if i+4 > len(b) {
		return 0, false
	}
	var v rune
	for _, c := range b[i : i+4] {
		var d byte
		switch {
		case '0' <= c && c <= '9':
			d = c - '0'
		case 'a' <= c && c <= 'f':
			d = c - 'a' + 10
		case 'A' <= c && c <= 'F':
			d = c - 'A' + 10
		default:
			return 0, false
		}
		v = v*16 + rune(d)
	}
	return v, true
}

// parseSnapshotTimestamp reads one timestamp value: null for a missing
// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
// distinct from null.
func parseSnapshotTimestamp(raw json.RawMessage) (*int64, error) {
	var t *int64
	if err := json.Unmarshal(raw, &t); err != nil {
		return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
	}
	if t != nil && *t < 0 {
		return nil, invalidSnapshot("timestamp must not be negative")
	}
	return t, nil
}

// parseSnapshotTxs reads one txs array, preserving duplicates and empty
// identifiers exactly as written. A null element is rejected, naming the
// block's height and the element's zero-based position, and so is an
// element whose raw string carries invalid UTF-8 bytes or unpaired or
// misordered surrogate escapes.
func parseSnapshotTxs(dec *json.Decoder, height int64) ([]string, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, classifySnapshotErr(err)
	}
	if delim, ok := tok.(json.Delim); !ok || delim != '[' {
		return nil, invalidSnapshot("field %q must be an array of strings", "txs")
	}
	txs := []string{}
	for dec.More() {
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
		}
		if isSnapshotNull(raw) {
			return nil, invalidSnapshot("block at height %d: txs element %d must not be null", height, len(txs))
		}
		var tx string
		if err := json.Unmarshal(raw, &tx); err != nil {
			return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
		}
		if !validSnapshotString(raw) {
			return nil, invalidSnapshot("block at height %d: field %q element %d has invalid UTF-8 or unpaired surrogate escapes", height, "txs", len(txs))
		}
		txs = append(txs, tx)
	}
	if _, err := dec.Token(); err != nil { // closing ']'
		return nil, classifySnapshotErr(err)
	}
	return txs, nil
}

// snapshotKey reads the next object key and returns the decoder's error
// unwrapped so each caller can classify it against its own input source.
func snapshotKey(dec *json.Decoder) (string, error) {
	tok, err := dec.Token()
	if err != nil {
		return "", err
	}
	key, ok := tok.(string)
	if !ok {
		return "", invalidSnapshot("object key must be a string")
	}
	return key, nil
}

// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
func invalidSnapshot(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
}

// classifySnapshotErr maps decoder failures onto the snapshot error model:
// malformed JSON, wrong value types, and truncation are snapshot errors,
// while anything else is an underlying read failure reported as-is.
func classifySnapshotErr(err error) error {
	var syntaxErr *json.SyntaxError
	var typeErr *json.UnmarshalTypeError
	switch {
	case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
		return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
	case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
		return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
	default:
		return fmt.Errorf("indexroom: read snapshot: %w", err)
	}
}

