129	func TestRestoreTimeStatsReferenceMatchesHandDerived(t *testing.T) {
130		if got, want := referenceTimeStats(restoreOldChainBlocks(), restoreStatsQuery), literalRestoreOldStats(); !reflect.DeepEqual(got, want) {
131			t.Fatalf("old-chain oracle=%+v\nwant=%+v", got, want)
132		}
133		if got, want := referenceTimeStats(restoreNewChainBlocks(), restoreStatsQuery), literalRestoreNewStats(); !reflect.DeepEqual(got, want) {
134			t.Fatalf("new-chain oracle=%+v\nwant=%+v", got, want)
135		}
