138	// The counting semantics the regression rests on, asserted directly for each
139	// chain so the guarantees do not hide inside a DeepEqual.
140	func TestRestoreTimeStatsCountingSemanticsOnBothChains(t *testing.T) {
141		old := literalRestoreOldStats()
142		if old.Buckets[0].TxCount != 2 || old.Buckets[0].DistinctTxIDs != 1 {
143			t.Fatalf("old [0,10): duplicate a must count twice but as one id: %+v", old.Buckets[0])
144		}
145		if old.Totals.DistinctTxIDs != 3 { // a in two segments counts once over the window
146			t.Fatalf("old window distinct must dedup a across segments: %+v", old.Totals)
147		}
148		if old.MissingTimeBlocks != 1 || old.Totals.Blocks != 3 {
149			t.Fatalf("time-less h3 counts toward missing but never toward blocks: %+v", old)
150		}
151		if old.ToHeight != 4 {
152			t.Fatalf("old upper height must pin tip 4: %+v", old)
153		}
154	
155		newStats := literalRestoreNewStats()
156		if len(newStats.Buckets) != 3 || newStats.Buckets[1] != (TimeBucket{Start: 10, End: 20}) {
157			t.Fatalf("empty [10,20) segment must still be returned zeroed: %+v", newStats.Buckets)
158		}
159		if newStats.Buckets[2].TxCount != 3 || newStats.Buckets[2].DistinctTxIDs != 2 {
160			t.Fatalf("new [20,30): d twice counts twice but as one id: %+v", newStats.Buckets[2])
161		}
162		if newStats.Totals.TxCount != 4 || newStats.Totals.DistinctTxIDs != 2 {
163			t.Fatalf("new totals: %+v", newStats.Totals)
164		}
165		if newStats.MissingTimeBlocks != 0 || newStats.ToHeight != 2 {
166			t.Fatalf("new chain has no missing time and tip 2: %+v", newStats)
167		}
168	}
