170	// A valid restore replaces the whole chain: after it returns, a new query
171	// reflects only the snapshot chain and no old height survives anywhere.
172	func TestQueryTimeStatsBeforeAndAfterRestore(t *testing.T) {
173		index := buildRestoreOldChain(t)
174	
175		before, err := index.QueryTimeStats(restoreStatsQuery)
176		if err != nil {
177			t.Fatal(err)
178		}
179		if !reflect.DeepEqual(before, literalRestoreOldStats()) {
180			t.Fatalf("pre-restore stats=%+v\nwant=%+v", before, literalRestoreOldStats())
181		}
182	
183		if err := index.Restore(strings.NewReader(restoreNewSnapshot)); err != nil {
184			t.Fatalf("restore refused: %v", err)
185		}
186		if index.Tip != 2 {
187			t.Fatalf("tip=%d, want restored tip 2", index.Tip)
188		}
189	
190		after, err := index.QueryTimeStats(restoreStatsQuery)
191		if err != nil {
192			t.Fatal(err)
193		}
194		if !reflect.DeepEqual(after, literalRestoreNewStats()) {
195			t.Fatalf("post-restore stats not wholly on the new chain:\n%+v", after)
196		}
197		// No residue of the replaced chain: heights 3 and 4 and their hashes are
198		// gone, and none of the old transactions leak into any count.
199		for _, height := range []int64{3, 4} {
200			if _, ok := index.Blocks[height]; ok {
201				t.Fatalf("replaced height %d still present", height)
202			}
203		}
204		for _, gone := range []string{"h1", "h2", "h3", "h4"} {
205			if _, ok := index.ByHash[gone]; ok {
206				t.Fatalf("replaced hash %s still indexed", gone)
207			}
208		}
209		if after.ToHeight != 2 || after.MissingTimeBlocks != 0 {
210			t.Fatalf("old tip or missing-time count leaked into post-restore stats: %+v", after)
211		}
212		if after.Totals.TxCount != 4 || after.Totals.DistinctTxIDs != 2 {
213			t.Fatalf("old-chain transactions leaked into post-restore totals: %+v", after.Totals)
214		}
215	}
216	
217	// gatedReader delivers the first prefix bytes of data, then parks until
218	// release is closed, then delivers the rest. It lets a test hold Restore
219	// mid-parse — after whole blocks have already been consumed but before the
220	// replacement is applied — without any sleeps or scheduling luck.
221	type gatedReader struct {
222		data    []byte
223		prefix  int
224		off     int
225		entered chan struct{}
226		release chan struct{}
227		once    sync.Once
228	}
229	
230	func newGatedReader(t *testing.T, data, cutMarker string) *gatedReader {
231		t.Helper()
232		prefix := strings.Index(data, cutMarker)
233		if prefix <= 0 {
234			t.Fatalf("test setup: cut marker %q not found in %q", cutMarker, data)
235		}
236		return &gatedReader{
237			data:    []byte(data),
238			prefix:  prefix,
239			entered: make(chan struct{}),
240			release: make(chan struct{}),
241		}
242	}
243	
244	func (r *gatedReader) Read(p []byte) (int, error) {
245		if r.off < r.prefix {
246			n := copy(p, r.data[r.off:r.prefix])
247			r.off += n
248			return n, nil
249		}
250		r.once.Do(func() { close(r.entered) })
251		<-r.release
252		if r.off >= len(r.data) {
253			return 0, io.EOF
254		}
255		n := copy(p, r.data[r.off:])
256		r.off += n
257		return n, nil
258	}
259	
260	// While the snapshot is still being read, the restore holds no lock: a stats
261	// query issued at that moment completes and answers from the complete old
262	// chain. Once the read finishes and the replacement lands, new queries answer
263	// from the complete new chain.
264	func TestQueryTimeStatsWhileRestoreStillReading(t *testing.T) {
265		index := buildRestoreOldChain(t)
266		// Park the read just before the second block object: the first block has
267		// already been consumed, the replacement is nowhere near applied.
268		reader := newGatedReader(t, restoreNewSnapshot, `{"height":2`)
269	
270		restoreDone := make(chan error, 1)
271		go func() {
272			restoreDone <- index.Restore(reader)
273		}()
274		<-reader.entered // restore is parked mid-stream, holding no lock
275	
276		stats, err := index.QueryTimeStats(restoreStatsQuery)
277		if err != nil {
278			t.Fatalf("query during snapshot read failed: %v", err)
279		}
280		if !reflect.DeepEqual(stats, literalRestoreOldStats()) {
281			t.Fatalf("query during snapshot read must see the complete old chain:\n%+v", stats)
282		}
283		select {
284		case err := <-restoreDone:
285			t.Fatalf("restore returned while its input was still gated: %v", err)
286		default:
287		}
288	
289		close(reader.release)
290		if err := <-restoreDone; err != nil {
291			t.Fatalf("restore after release failed: %v", err)
292		}
293		stats, err = index.QueryTimeStats(restoreStatsQuery)
294		if err != nil {
295			t.Fatal(err)
296		}
297		if !reflect.DeepEqual(stats, literalRestoreNewStats()) {
298			t.Fatalf("query after completed restore must see the complete new chain:\n%+v", stats)
299		}
300	}
301	
302	// A query that has pinned the OLD tip (4) and still holds the lock when the
303	// restore's replacement is ready must finish on the complete old chain; the
304	// restore applies only afterwards.
305	func TestQueryTimeStatsInFlightObservesCompleteOldChainBeforeRestore(t *testing.T) {
306		index := buildRestoreOldChain(t)
307	
308		queryParked := make(chan struct{})
309		releaseQuery := make(chan struct{})
310		var hookOnce sync.Once
311		statsQueryHookLocked = func(to int64) {
312			if to != 4 {
313				t.Errorf("stats hook resolved to=%d, want old tip 4", to)
314			}
315			hookOnce.Do(func() { close(queryParked) })
316			<-releaseQuery
317		}
318		t.Cleanup(func() { statsQueryHookLocked = nil })
319	
320		result := make(chan TimeStats, 1)
321		errCh := make(chan error, 1)
322		go func() {
323			stats, err := index.QueryTimeStats(restoreStatsQuery)
324			if err != nil {
325				errCh <- err
326				return
327			}
328			result <- stats
329		}()
330		<-queryParked // query holds index.mu and has pinned tip 4
331	
332		restoreDone := make(chan error, 1)
333		go func() {
334			// strings.Reader is fully readable, so this restore parses the whole
335			// snapshot and then blocks on index.mu behind the parked query.
336			restoreDone <- index.Restore(strings.NewReader(restoreNewSnapshot))
337		}()
338	
339		close(releaseQuery) // the query scans and finishes on the old chain first
340		var got TimeStats
341		select {
342		case got = <-result:
343		case err := <-errCh:
344			t.Fatalf("concurrent query failed: %v", err)
345		}
346		if !reflect.DeepEqual(got, literalRestoreOldStats()) {
347			t.Fatalf("query holding the lock across restore commit must see the old chain:\n%+v", got)
348		}
349		if err := classifyTimeStats(got, literalRestoreOldStats(), literalRestoreNewStats()); err != nil {
350			t.Fatalf("in-flight query did not return one complete chain:\n%v", err)
351		}
352		statsQueryHookLocked = nil // the rendezvous is spent; later queries run free
353		if err := <-restoreDone; err != nil {
354			t.Fatalf("restore failed: %v", err)
355		}
356		stats, err := index.QueryTimeStats(restoreStatsQuery)
357		if err != nil {
358			t.Fatal(err)
359		}
360		if !reflect.DeepEqual(stats, literalRestoreNewStats()) {
361			t.Fatalf("query after restore must see the complete new chain:\n%+v", stats)
362		}
363	}
364	
365	// A query issued while a successful restore has installed the new chain but
366	// not yet returned must wait and then observe the complete NEW chain,
367	// including the shortened upper height.
368	func TestQueryTimeStatsIssuedAtRestoreCommitSeesNewChain(t *testing.T) {
369		index := buildRestoreOldChain(t)
370	
371		restoreParked := make(chan struct{})
372		releaseRestore := make(chan struct{})
373		var hookOnce sync.Once
374		restoreAppliedHookLocked = func(newTip int64) {
375			if newTip != 2 {
376				t.Errorf("restore hook saw newTip=%d, want 2", newTip)
377			}
378			hookOnce.Do(func() { close(restoreParked) })
379			<-releaseRestore
380		}
381		t.Cleanup(func() { restoreAppliedHookLocked = nil })
382	
383		restoreDone := make(chan error, 1)
384		go func() {
385			restoreDone <- index.Restore(strings.NewReader(restoreNewSnapshot))
386		}()
387		<-restoreParked // new chain installed (tip 2), Restore still holds the lock
388	
389		result := make(chan TimeStats, 1)
390		go func() {
391			stats, err := index.QueryTimeStats(restoreStatsQuery)
392			if err != nil {
393				t.Errorf("query during restore commit failed: %v", err)
394				return
395			}
396			result <- stats
397		}()
398		select {
399		case got := <-result:
400			t.Fatalf("query returned while the restore still held the lock: %+v", got)
401		default:
402		}
403	
404		close(releaseRestore)
405		if err := <-restoreDone; err != nil {
406			t.Fatalf("restore failed: %v", err)
407		}
408		got := <-result
409		if err := classifyTimeStats(got, literalRestoreOldStats(), literalRestoreNewStats()); err != nil {
410			t.Fatalf("query across restore commit did not return one complete chain:\n%v", err)
411		}
412		if !reflect.DeepEqual(got, literalRestoreNewStats()) {
413			t.Fatalf("query after restore commit must see the complete new chain:\n%+v", got)
414		}
415	}
416	
417	// A snapshot whose LAST block carries an illegal negative timestamp is
418	// rejected with ErrInvalidSnapshot only after the earlier blocks were already
419	// read. Nothing of them may remain: the old chain stays bit-for-bit in
420	// effect, before and after the failed restore.
421	func TestRestoreInvalidNegativeTimeAtLastBlockKeepsOldChain(t *testing.T) {
422		index := buildRestoreOldChain(t)
423		// Park the read just before the second (poisoned) block: the first block
424		// of the snapshot has been fully consumed when the restore stalls.
425		reader := newGatedReader(t, restoreNegativeTimeSnapshot, `{"height":2`)
426	
427		restoreDone := make(chan error, 1)
428		go func() {
429			restoreDone <- index.Restore(reader)
430		}()
431		<-reader.entered
432	
433		stats, err := index.QueryTimeStats(restoreStatsQuery)
434		if err != nil {
435			t.Fatalf("query during gated read failed: %v", err)
436		}
437		if !reflect.DeepEqual(stats, literalRestoreOldStats()) {
438			t.Fatalf("query while the invalid snapshot is still reading must see the old chain:\n%+v", stats)
439		}
440	
441		close(reader.release)
442		if err := <-restoreDone; !errors.Is(err, ErrInvalidSnapshot) {
443			t.Fatalf("restore err=%v, want ErrInvalidSnapshot", err)
444		}
445	
446		// The rejected restore changed nothing: stats still match the old chain
447		// exactly and no partially read snapshot block survived.
448		stats, err = index.QueryTimeStats(restoreStatsQuery)
449		if err != nil {
450			t.Fatal(err)
451		}
452		if !reflect.DeepEqual(stats, literalRestoreOldStats()) {
453			t.Fatalf("stats after rejected restore differ from the old chain:\n%+v", stats)
454		}
455		if index.Tip != 4 || len(index.Blocks) != 4 {
456			t.Fatalf("rejected restore left tip=%d blocks=%d, want tip 4 with 4 blocks", index.Tip, len(index.Blocks))
457		}
458		if index.Blocks[3].Time != nil {
459			t.Fatalf("time-less h3 gained a timestamp from the rejected snapshot: %+v", index.Blocks[3])
460		}
461		for _, hash := range []string{"h1", "h2", "h3", "h4"} {
462			if _, ok := index.ByHash[hash]; !ok {
463				t.Fatalf("old hash %s lost after rejected restore", hash)
464			}
465		}
466		for _, leaked := range []string{"j1", "j2"} {
467			if _, ok := index.ByHash[leaked]; ok {
468				t.Fatalf("hash %s from the rejected snapshot was left indexed", leaked)
469			}
470		}
471		if stats.MissingTimeBlocks != 1 || stats.ToHeight != 4 {
472			t.Fatalf("rejected snapshot altered the missing-time count or upper height: %+v", stats)
473		}
474	}
475	
476	// The complete-chain validator must catch exactly the mixtures this
477	// regression targets: old-chain transaction counts paired with the new
478	// chain's height bound, missing-time count, or dedup result (and vice versa).
479	func TestClassifyTimeStatsRejectsRestoreMixtures(t *testing.T) {
480		oldRef, newRef := literalRestoreOldStats(), literalRestoreNewStats()
481		if err := classifyTimeStats(oldRef, oldRef, newRef); err != nil {
482			t.Fatalf("pure old answer rejected: %v", err)
483		}
484		if err := classifyTimeStats(newRef, oldRef, newRef); err != nil {
485			t.Fatalf("pure new answer rejected: %v", err)
486		}
487	
488		// Old transaction counts and dedup under the NEW upper height.
489		mixed := oldRef
490		mixed.ToHeight = newRef.ToHeight
491		if err := classifyTimeStats(mixed, oldRef, newRef); err == nil {
492			t.Fatal("old counts under the new tip height were accepted")
493		} else if !strings.Contains(err.Error(), "MIXED") {
494			t.Fatalf("old-counts/new-height mixture not reported as MIXED:\n%v", err)
495		}
496	
497		// New transaction counts under the OLD upper height and missing count.
498		mixed = newRef
499		mixed.ToHeight = oldRef.ToHeight
500		mixed.MissingTimeBlocks = oldRef.MissingTimeBlocks
501		if err := classifyTimeStats(mixed, oldRef, newRef); err == nil {
502			t.Fatal("new counts under the old tip and missing count were accepted")
503		} else if !strings.Contains(err.Error(), "MIXED") {
504			t.Fatalf("new-counts/old-height mixture not reported as MIXED:\n%v", err)
505		}
506	
507		// Old per-bucket content with the new chain's dedup result in the totals.
508		mixed = oldRef
509		mixed.Totals.DistinctTxIDs = newRef.Totals.DistinctTxIDs
510		if err := classifyTimeStats(mixed, oldRef, newRef); err == nil {
511			t.Fatal("old buckets with the new dedup total were accepted")
512		}
513	}
514	
515	// Sustained overlap: restores alternate between the old-chain snapshot and
516	// the new-chain snapshot while readers query continuously. Every answer must
517	// classify as one complete chain; success never depends on which side of a
518	// restore a query happened to land. This is a supplement to the deterministic
519	// rendezvous tests above, not a substitute: those pin the interleavings, this
520	// one sweeps for anything they missed.
521	func TestQueryTimeStatsRepeatedRestoresStayConsistent(t *testing.T) {
522		index := buildRestoreOldChain(t)
523		oldSnapshot := exportString(t, index) // version 2: the chain has timestamps
524		oldRef, newRef := literalRestoreOldStats(), literalRestoreNewStats()
525	
526		const restorers = 2
527		const rounds = 40
528		const readers = 4
529		const reads = 80
530	
531		stop := make(chan struct{})
532		var wg sync.WaitGroup
533		for r := 0; r < restorers; r++ {
534			wg.Add(1)
535			go func(seed int) {
536				defer wg.Done()
537				for i := 0; i < rounds; i++ {
538					select {
539					case <-stop:
540						return
541					default:
542					}
543					snapshot := restoreNewSnapshot
544					if (i+seed)%2 == 0 {
545						snapshot = oldSnapshot
546					}
547					if err := index.Restore(strings.NewReader(snapshot)); err != nil {
548						t.Errorf("restore failed: %v", err)
549						return
550					}
551				}
552			}(r)
553		}
554		for r := 0; r < readers; r++ {
555			wg.Add(1)
556			go func() {
557				defer wg.Done()
558				for i := 0; i < reads; i++ {
559					select {
560					case <-stop:
561						return
562					default:
563					}
564					stats, err := index.QueryTimeStats(restoreStatsQuery)
565					if err != nil {
566						t.Errorf("query failed: %v", err)
567						return
568					}
569					if err := classifyTimeStats(stats, oldRef, newRef); err != nil {
570						t.Errorf("%v", err)
571						return
572					}
573				}
574			}()
575		}
576		wg.Wait()
577		close(stop)
578	
579		// Leave the index deterministically on the new chain and re-verify.
580		if err := index.Restore(strings.NewReader(restoreNewSnapshot)); err != nil {
581			t.Fatalf("final restore failed: %v", err)
582		}
583		final, err := index.QueryTimeStats(restoreStatsQuery)
584		if err != nil {
585			t.Fatal(err)
586		}
587		if !reflect.DeepEqual(final, newRef) {
588			t.Fatalf("final state is not the complete new chain:\n%+v", final)
589		}
590	}
